mapper.update:

		UPDATE KEPMGPHD /*updateMdCmStndKEPMGPHD*/
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}


		UPDATE KEPMGPDT /*updateRejectKEPMGPDT*/
		  SET STATUS = #{STATUS}            
               , CONFIRM_DATE = SYSDATE  
               , CONFIRM_USER_ID = #{USER_ID} 
               , CHANGE_DATE = SYSDATE
	       WHERE BUYER = #{KEY_2}
	           AND PM_NO = #{KEY_1}

   /*commonMdCmStndApproval.updateMdcmStndCmscatlgAdd*/  

			UPDATE CMSCATLG_ADD
			SET STATUS = 'P'
			WHERE PM_NO = #{KEY_1}

   /*commonMdCmStndApproval.updateMdcmCmsCatlgApprAdd*/  

			UPDATE CMSCATLG_ADD
			SET STATUS =#{ADD_STATUS}
			WHERE PM_NO = #{KEY_1}

   /*commonMdCmStndApproval.updateMdcmCmsCatlgIdAdd*/  

			UPDATE CMSCATLG_ADD  A
			SET   CMS_CATLG_ID = (SELECT CMS_CATLG_ID FROM CMSCATLG B WHERE B.PM_NO = A.PM_NO AND B.PM_SEQ = A.PM_SEQ)
			WHERE PM_NO = #{KEY_1}

